"""Helpers for API reference pages generated by TypeDoc (typedoc-plugin-markdown).

Pinia and Vue Router document their API with one generated page per exported symbol
(``api/functions/useRouter.md``, ``api/interfaces/RouterOptions.md``, ...). Upstream produces
them with ``node run-typedoc.mjs`` inside the pnpm workspace, which executes third-party code.
Docker builds therefore generate the pages in a separate stage that holds no secrets, and
ingestion installs the finished markdown. Developer machines with Node generate them locally.
"""

import logging
import os
import re
import shutil
import subprocess
from collections.abc import Iterator
from pathlib import Path

from vue_docs_core.config import settings

logger = logging.getLogger(__name__)

# TypeDoc groups symbols into one folder per kind; these hold types rather than callable APIs.
TYPE_FOLDERS = frozenset({"interfaces", "type-aliases", "enumerations", "classes"})

_SYMBOL_RE = re.compile(r"^[A-Za-z$][\w$]*$")
# Generated pages open with VitePress frontmatter and a breadcrumb of relative links. The
# parser may already have dropped the opening "---" delimiter, so it is optional here.
_FRONTMATTER_RE = re.compile(r"\A(?:---\n)?editLink: false\n---\n+")
_BREADCRUMB_RE = re.compile(r"\A\[[^\]\n]+\]\((?:\.\./)*index\.md\)[^\n]*\n+")
_SECRET_MARKERS = ("KEY", "SECRET", "TOKEN", "PASSWORD", "DATABASE_URL")


def iter_symbol_pages(api_dir: Path, docs_path: Path) -> Iterator[tuple[str, str, str]]:
    """Yield ``(symbol, page path relative to docs_path, kind folder)`` per API page.

    TypeDoc names every page after its symbol, which is more reliable than parsing the H1
    (``# DefineStoreOptions\\<Id, S\\>``). Index pages, the ``default`` export and private
    names with a leading underscore are skipped.
    """
    for md_file in sorted(api_dir.rglob("*.md")):
        symbol = md_file.stem
        if md_file.name == "index.md" or symbol == "default" or not _SYMBOL_RE.match(symbol):
            continue
        yield symbol, str(md_file.relative_to(docs_path)), md_file.parent.name


def strip_typedoc_boilerplate(raw: str) -> str:
    """Drop the frontmatter and breadcrumb line that open every generated page.

    Both are noise in the text that gets embedded. Hand-written pages never match.
    """
    return _BREADCRUMB_RE.sub("", _FRONTMATTER_RE.sub("", raw, count=1), count=1)


def install_prebuilt_api(source: str, api_dir: Path) -> bool:
    """Copy prebuilt API pages for ``source`` into ``api_dir``. Returns True if installed."""
    if not settings.typedoc_dir:
        return False
    prebuilt = Path(settings.typedoc_dir) / source / "api"
    if not any(prebuilt.rglob("*.md")):
        logger.warning("No prebuilt TypeDoc pages for %s in %s", source, prebuilt)
        return False
    shutil.copytree(prebuilt, api_dir, dirs_exist_ok=True)
    logger.info(
        "Installed %d prebuilt TypeDoc pages for %s", len(list(api_dir.rglob("*.md"))), source
    )
    return True


def generate_api_docs(repo_root: Path) -> None:
    """Generate the API pages locally with the upstream script. Needs Node and network access.

    Skips quietly without Node or when pages already exist. The subprocesses run without
    secret-looking environment variables, since they execute the upstream repo's dependencies.
    """
    docs_dir = repo_root / "packages" / "docs"
    api_dir = docs_dir / "api"
    if any(api_dir.rglob("*.md")):
        logger.info("TypeDoc API docs already exist, skipping generation")
        return
    if not (docs_dir / "run-typedoc.mjs").exists():
        logger.warning("run-typedoc.mjs not found, cannot generate API docs")
        return
    if not shutil.which("node") or not shutil.which("npx"):
        logger.info("node/npx not available, skipping TypeDoc generation")
        return

    env = {k: v for k, v in os.environ.items() if not any(m in k.upper() for m in _SECRET_MARKERS)}
    logger.info("Generating TypeDoc API docs (pnpm install, then run-typedoc.mjs)...")
    # pnpm self-selects the version pinned in the repo's packageManager field.
    install = subprocess.run(
        ["npx", "-y", "pnpm@12", "install", "--frozen-lockfile", "--ignore-scripts"],
        cwd=str(repo_root),
        capture_output=True,
        text=True,
        timeout=600,
        env={**env, "CI": "true"},
    )
    if install.returncode != 0:
        logger.warning("pnpm install failed (seed entities only): %s", install.stderr[-500:])
        return
    result = subprocess.run(
        ["node", "run-typedoc.mjs"],
        cwd=str(docs_dir),
        capture_output=True,
        text=True,
        timeout=300,
        env=env,
    )
    if result.returncode != 0:
        logger.warning("TypeDoc generation failed (seed entities only): %s", result.stderr[-500:])
    else:
        logger.info("TypeDoc generated %d API doc files", len(list(api_dir.rglob("*.md"))))
